import {BUNDLE_LIMITS,preparePrivateWalSave,reopenPrivateWalBundle,privateWalView} from './contribution-wal-bundle.js';
// This adapter uses only explicit file reads, inert text rendering and user downloads.
export function mountContributionWal(doc=document){
 const get=id=>doc.getElementById('wal-'+id);let epoch=0,prepared=null,current=null,busy=false;
 const status=s=>{get('status').textContent=s;};
 function invalidate(){epoch++;prepared=null;get('download').disabled=true;get('csv-download').disabled=true;status('Inputs changed. Inspect again before downloading a new result. The kept archive remains available unchanged.');}
 function ready(value){prepared=value;current=value;get('download').disabled=false;get('csv-download').disabled=false;get('prior-download').disabled=false;get('record').value=value.verification.rows[0].record_id;get('record').readOnly=true;get('prior-kept').checked=false;}
 function expected(){return {expectedGenesis:get('genesis').value.trim()||null,expectedTip:get('tip').value.trim()||null};}
 async function readFile(id,max){const files=get(id).files; if(!files||files.length!==1)throw Error('Select exactly one file.');const file=files[0];if(file.size<=0||file.size>max)throw Error('Selected file exceeds its byte budget or is empty.');const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length!==file.size||bytes.length>max)throw Error('File byte count changed.');return bytes;}
 async function run(action){if(busy)return;const ticket=epoch;busy=true;get('inspect').disabled=true;get('reopen').disabled=true;try{if(!get('local-only').checked)throw Error('Confirm local-only inspection and download first.');status('Inspecting exact local bytes…');const value=await action();const view=await privateWalView(value);if(ticket!==epoch){status('Inputs changed during inspection. Result discarded; prior archive preserved.');return;}ready(value);const v=value.verification;get('summary').textContent=JSON.stringify({schema:v.schema,rows:v.rows.length,genesis:v.genesis,tip:v.tip,trust:v.trust,freshness:v.freshness,identity:'UNAUTHENTICATED',rights:'NOT_VERIFIED',admission:'NOT_PERFORMED',audience:'private_local_review',sourceBytes:'NOT_CARRIED',exactArtifacts:value.snapshots.size,priorExactWals:value.priorWals.length,independentCheckpointReminder:'Retain pins separately. These displayed values are not an independent checkpoint.'},null,2);get('view').textContent=view.text;status('Inspected private archive is ready to download. No sharing or admission occurred.');}catch(e){if(ticket===epoch)status('Inspection refused: '+e.message+' Prior kept archive remains unchanged.');}finally{busy=false;get('inspect').disabled=false;get('reopen').disabled=false;}}
 get('inspect').addEventListener('click',()=>run(async()=>{const bytes=await readFile('packet-file',BUNDLE_LIMITS.packetBytes);return preparePrivateWalSave({packetBytes:bytes,creator:get('creator').value,recordId:get('record').value,eventId:get('event').value,purpose:get('purpose').value,method:get('method').value,savedAt:new Date().toISOString(),localOnly:get('local-only').checked,previous:current,expected:expected(),priorKept:get('prior-kept').checked});}));
 get('reopen').addEventListener('click',()=>run(async()=>{if(current&&!get('prior-kept').checked)throw Error('Keep/download the prior archive before replacing its view.');return reopenPrivateWalBundle(await readFile('bundle-file',BUNDLE_LIMITS.fileBytes),expected());}));
 function download(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type})),a=doc.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 get('download').addEventListener('click',()=>{if(prepared&&get('local-only').checked)download(prepared.bundleBytes,'private-contribution-wal-bundle.json','application/json');});
 get('csv-download').addEventListener('click',()=>{if(prepared&&get('local-only').checked)download(prepared.bytes,'private-experimental-WAL.csv','text/csv;charset=utf-8');});
 get('prior-download').addEventListener('click',()=>{if(current&&get('local-only').checked)download(current.bundleBytes,'kept-private-contribution-wal-bundle.json','application/json');});
 for(const node of doc.querySelectorAll('input,textarea')){node.addEventListener('input',invalidate);node.addEventListener('change',invalidate);}
 return {invalidate};
}
if(typeof document!=='undefined')mountContributionWal();
